// Package api defines interfaces and context utilities used by the Temporal plugin,
// including pool, codec, server, and interceptor abstractions.
package api

package api

import (
	"context"

	commonpb "go.temporal.io/api/common/v1"
)

type ContextKey struct {
	name string
}

func (ck *ContextKey) String() string {
	return ck.name
}

var (
	// HeaderContextKey is RR <-> Temporal context key
	HeaderContextKey = &ContextKey{name: "headers"} //nolint:gochecknoglobals
)

func ActivityHeadersFromCtx(ctx context.Context) *commonpb.Header {
	val, _ := ctx.Value(HeaderContextKey).(map[string]*commonpb.Payload)
	if len(val) == 0 {
		return nil
	}
	return &commonpb.Header{Fields: val}
}

package api

import (
	"context"
	"log/slog"
	"time"

	"github.com/roadrunner-server/pool/v2/payload"
	"github.com/roadrunner-server/pool/v2/pool"
	"github.com/roadrunner-server/pool/v2/state/process"
	"github.com/roadrunner-server/pool/v2/worker"
	"github.com/temporalio/roadrunner-temporal/v6/internal"
	"go.temporal.io/sdk/interceptor"

	staticPool "github.com/roadrunner-server/pool/v2/pool/static_pool"
)

type Interceptor interface {
	WorkerInterceptor() interceptor.WorkerInterceptor
	Name() string
}

type Pool interface {
	// Workers return a worker list associated with the pool.
	Workers() (workers []*worker.Process)
	// RemoveWorker removes worker from the pool.
	RemoveWorker(ctx context.Context) error
	// AddWorker adds worker to the pool.
	AddWorker() error
	// QueueSize can be implemented on the pool to provide the request queue information
	QueueSize() uint64
	// Reset kill all workers inside the watcher and replaces with new
	Reset(ctx context.Context) error
	// Exec payload
	Exec(ctx context.Context, p *payload.Payload, stopCh chan struct{}) (chan *staticPool.PExec, error)
}

type Codec interface {
	// Encode encodes messages and context to the payload for the worker
	Encode(ctx *internal.Context, p *payload.Payload, msg ...*internal.Message) error
	// Decode decodes payload from the worker to the proto-message
	Decode(pld *payload.Payload, msg *[]*internal.Message) error
	// DecodeWorkerInfo decode a call to get a worker info ID=0 (initial)
	DecodeWorkerInfo(p *payload.Payload, wi *[]*internal.WorkerInfo) error
}

// Informer used to get workers from a particular plugin or set of plugins
type Informer interface {
	Workers() []*process.State
}

type Configurer interface {
	// UnmarshalKey takes a single key and unmarshal it into a Struct.
	UnmarshalKey(name string, out any) error
	// Has checks if a config section exists.
	Has(name string) bool
	// GracefulTimeout represents timeout for all servers registered in the endure
	GracefulTimeout() time.Duration
	// RRVersion returns running RR version
	RRVersion() string
	// Experimental returns true if the plugin is experimental
	Experimental() bool
}

// Server creates workers for the application.
type Server interface {
	NewPool(ctx context.Context, cfg *pool.Config, env map[string]string, _ *slog.Logger) (*staticPool.Pool, error)
	NewPoolWithOptions(ctx context.Context, cfg *pool.Config, env map[string]string, _ *slog.Logger, options ...staticPool.Options) (*staticPool.Pool, error)
}

package rrtemporal

import (
	"context"
	"log/slog"
	"sync"
	"testing"
	"time"

	"github.com/roadrunner-server/events"
	"github.com/stretchr/testify/require"
	"github.com/temporalio/roadrunner-temporal/v6/internal"
	"go.temporal.io/sdk/worker"
)

const stopTestTimeout = 5 * time.Second

type blockingWorker struct {
	worker.Worker

	stopping chan struct{}
	release  chan struct{}
}

func (b *blockingWorker) Stop() {
	close(b.stopping)
	<-b.release
}

type drainingPlugin struct {
	plugin  *Plugin
	release func()
	stopped chan error
}

// startDraining leaves Stop blocked inside the shutdown, holding p.mu, which is
// where a heartbeat from a still-running activity arrives.
func startDraining(t *testing.T) *drainingPlugin {
	t.Helper()

	w := &blockingWorker{
		stopping: make(chan struct{}),
		release:  make(chan struct{}),
	}

	p := &Plugin{
		log:    slog.New(slog.DiscardHandler),
		stopCh: make(chan struct{}, 1),
		temporal: &temporal{
			activities: map[string]*internal.ActivityInfo{},
			workflows:  map[string]*internal.WorkflowInfo{},
			workers:    []worker.Worker{w},
		},
	}
	p.eventBus, p.id = events.NewEventBus()

	release := sync.OnceFunc(func() { close(w.release) })
	t.Cleanup(release)

	stopped := make(chan error, 1)
	go func() { stopped <- p.Stop(context.Background()) }()

	select {
	case <-w.stopping:
	case <-time.After(stopTestTimeout):
		require.FailNow(t, "Stop did not reach the worker drain")
	}

	return &drainingPlugin{plugin: p, release: release, stopped: stopped}
}

func (d *drainingPlugin) finish(t *testing.T) {
	t.Helper()

	d.release()

	select {
	case err := <-d.stopped:
		require.NoError(t, err)
	case <-time.After(stopTestTimeout):
		require.FailNow(t, "Stop did not return after the drain finished")
	}
}

func TestDefinitionsAreReadableWhileStopping(t *testing.T) {
	d := startDraining(t)

	done := make(chan struct{})
	go func() {
		d.plugin.getActDef()
		d.plugin.getWfDef()
		close(done)
	}()

	select {
	case <-done:
	case <-time.After(stopTestTimeout):
		require.FailNow(t, "reading the activity definition blocked while the plugin was stopping")
	}

	d.finish(t)
}

package dataconverter

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"go.temporal.io/api/common/v1"
	"go.temporal.io/sdk/converter"
)

func Test_Passthough(t *testing.T) {
	codec := NewDataConverter(converter.GetDefaultDataConverter())

	value, err := codec.ToPayloads("tests")
	assert.NoError(t, err)

	out := &common.Payloads{}

	assert.Len(t, out.Payloads, 0)
	assert.NoError(t, codec.FromPayloads(value, &out))

	assert.Len(t, out.Payloads, 1)
}

package canceller

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
)

func Test_CancellerNoListeners(t *testing.T) {
	c := &Canceller{}

	assert.NoError(t, c.Cancel(1))
}

func Test_CancellerListenerError(t *testing.T) {
	c := &Canceller{}
	c.Register(1, func() error {
		return errors.New("failed")
	})

	assert.Error(t, c.Cancel(1))
}

func Test_CancellerListenerDiscarded(t *testing.T) {
	c := &Canceller{}
	c.Register(1, func() error {
		return errors.New("failed")
	})

	c.Discard(1)
	assert.NoError(t, c.Cancel(1))
}

package internal

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/require"
	commonpb "go.temporal.io/api/common/v1"
	"go.temporal.io/sdk/converter"
	bindings "go.temporal.io/sdk/internalbindings"
	"go.temporal.io/sdk/temporal"
	"go.temporal.io/sdk/workflow"
)

type stubWorkflowEnvironment struct {
	bindings.WorkflowEnvironment

	info             *workflow.Info
	dataConverter    converter.DataConverter
	failureConverter converter.FailureConverter
}

func (e *stubWorkflowEnvironment) WorkflowInfo() *workflow.Info { return e.info }
func (e *stubWorkflowEnvironment) GetDataConverter() converter.DataConverter {
	return e.dataConverter
}
func (e *stubWorkflowEnvironment) GetFailureConverter() converter.FailureConverter {
	return e.failureConverter
}

func TestLocalActivityParams_FailureConverterDoesNotPanic(t *testing.T) {
	env := &stubWorkflowEnvironment{
		info:             &workflow.Info{TaskQueueName: "tq"},
		dataConverter:    converter.GetDefaultDataConverter(),
		failureConverter: temporal.GetDefaultFailureConverter(),
	}
	params := ExecuteLocalActivity{Name: "X"}.LocalActivityParams(
		env, func() {}, &commonpb.Payloads{}, &commonpb.Header{},
	)

	require.NotPanics(t, func() {
		_ = params.FailureConverter.ErrorToFailure(errors.New("boom"))
	})
}

package queue

import (
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/temporalio/roadrunner-temporal/v6/internal"
	"go.temporal.io/api/common/v1"
	"go.temporal.io/api/failure/v1"
)

func Test_MessageQueueFlushError(t *testing.T) {
	var index uint64
	mq := NewMessageQueue(func() uint64 {
		return atomic.AddUint64(&index, 1)
	})

	mq.PushError(1, &failure.Failure{}, 0)
	assert.Len(t, mq.Messages(), 1)

	mq.Flush()
	assert.Len(t, mq.Messages(), 0)
	assert.Equal(t, uint64(0), index)
}

func Test_MessageQueueFlushResponse(t *testing.T) {
	var index uint64
	mq := NewMessageQueue(func() uint64 {
		return atomic.AddUint64(&index, 1)
	})

	mq.PushResponse(1, &common.Payloads{}, 0)
	assert.Len(t, mq.Messages(), 1)

	mq.Flush()
	assert.Len(t, mq.Messages(), 0)
	assert.Equal(t, uint64(0), index)
}

func Test_MessageQueueCommandID(t *testing.T) {
	var index uint64
	mq := NewMessageQueue(func() uint64 {
		return atomic.AddUint64(&index, 1)
	})

	mq.PushCommand(internal.StartWorkflow{}, &common.Payloads{}, &common.Header{}, 0)
	assert.Len(t, mq.Messages(), 1)

	mq.Flush()
	assert.Len(t, mq.Messages(), 0)
}
